define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_87.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e302470","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_87.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e302574","topics":[]},{"title":"Applying LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Apply LOTO to both the gradient and system Power Distribution Unit (PDU) breakers on the MDP when servicing either of these items in the ISC. Apply LOTO to make sure of a safe environment when working on these parts.<\/p>","href":"t_Applying-LOTO-ISC_77.html","attributes":{"data-id":"id_2001781"},"menu":{"hasChildren":false},"tocID":"id_2001781-d46e302678","topics":[]},{"title":"Removing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Removes the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_RemovingTheServiceAccessTrim_30.html","attributes":{"data-id":"id_2002821"},"menu":{"hasChildren":false},"tocID":"id_2002821-d46e302782","topics":[]},{"title":"Removing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Removes the front service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheFrontServiceAccessPanel_28.html","attributes":{"data-id":"id_2002823"},"menu":{"hasChildren":false},"tocID":"id_2002823-d46e302886","topics":[]},{"title":"Removing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Removes the rear service access panel from the magnet to allow access to components mounted on the left-hand side of the magnet.<\/p>","href":"t_RemovingTheRearServiceAccessPanel_26.html","attributes":{"data-id":"id_2002966"},"menu":{"hasChildren":false},"tocID":"id_2002966-d46e302990","topics":[]},{"title":"Removing the Physiological Acquisition Controller (PAC)","shortdesc":"<p class=\"shortdesc\">Remove the Physiological Acquisition Controller (PAC) from the magnet outer electronics.<\/p>","href":"t_RemovingThePhysiologicalAcquisitionControllerPAC.html","attributes":{"data-id":"id_2001563"},"menu":{"hasChildren":false},"tocID":"id_2001563-d46e303094","topics":[]},{"title":"Installing the Physiological Acquisition Controller (PAC)","shortdesc":"<p class=\"shortdesc\">Install a Physiological Acquisition Controller (PAC) at the location indicated.<\/p>","href":"t_InstallingThePhysiologicalAcquisitionControllerPAC.html","attributes":{"data-id":"id_2014236"},"menu":{"hasChildren":false},"tocID":"id_2014236-d46e303198","topics":[]},{"title":"Installing the magnet rear service access panel","shortdesc":"<p class=\"shortdesc\">Installs the rear service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheRearServiceAccessPanel_25.html","attributes":{"data-id":"id_2002967"},"menu":{"hasChildren":false},"tocID":"id_2002967-d46e303302","topics":[]},{"title":"Installing the magnet front service access panel","shortdesc":"<p class=\"shortdesc\">Installs the front service access panel onto the magnet enclosure. This panel covers the components mounted on the left-hand side of the magnet.<\/p>","href":"t_InstallingTheFrontServiceAccessPanel_27.html","attributes":{"data-id":"id_2002825"},"menu":{"hasChildren":false},"tocID":"id_2002825-d46e303406","topics":[]},{"title":"Installing the magnet service access trim","shortdesc":"<p class=\"shortdesc\">Installs the service access trim. The trim panel covers the screws securing the front and rear service access panels.<\/p>","href":"t_InstallingTheServiceAccessTrim_29.html","attributes":{"data-id":"id_2002822"},"menu":{"hasChildren":false},"tocID":"id_2002822-d46e303511","topics":[]},{"title":"Removing LOTO - ISC","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the gradient and system PDU breakers on the MDP before restoring power to the ISC.<\/p>","href":"t_Removing-LOTO-ISC_79.html","attributes":{"data-id":"id_2001783"},"menu":{"hasChildren":false},"tocID":"id_2001783-d46e303615","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_85.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e303719","topics":[]},{"title":"Finalizing the Physiological Acquisition Controller (PAC) replacement","shortdesc":"<p class=\"shortdesc\">This procedure finalizes the Physiological Acquisition Controller (PAC) replacement.<\/p>","href":"t_FinalizingThePhysiologicalAcquisitionControllerPACReplacement.html","attributes":{"data-id":"id_2014237"},"menu":{"hasChildren":false},"tocID":"id_2014237-d46e303823","topics":[]}]});